/// Returns `true` if and only if every element in `arr` has the same parity
/// as its index (i.e., even indices contain even numbers and odd indices
/// contain odd numbers). An empty array trivially satisfies this property.
pub fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    arr.iter()
       .enumerate()
       .all(|(i, &v)| v % 2 == i % 2)
}

#[cfg(test)]
mod tests {
    use super::is_odd_at_odd_index;

    #[test]
    fn test_empty() {
        let arr: Vec<usize> = vec![];
        assert!(is_odd_at_odd_index(&arr));
    }

    #[test]
    fn test_all_even_even_positions() {
        let arr = vec![0, 1, 2, 3, 4, 5];
        assert!(is_odd_at_odd_index(&arr)); // 0@0, 1@1, 2@2, ...
    }

    #[test]
    fn test_mismatch_even_position() {
        let arr = vec![1, 1, 2, 3];
        assert!(!is_odd_at_odd_index(&arr)); // 1@0 is odd at even index
    }

    #[test]
    fn test_mismatch_odd_position() {
        let arr = vec![0, 2, 2, 3];
        assert!(!is_odd_at_odd_index(&arr)); // 2@1 is even at odd index
    }

    #[test]
    fn test_longer_sequence() {
        let arr = vec![10, 11, 12, 13, 14, 15, 16, 17];
        assert!(is_odd_at_odd_index(&arr));
    }
}